%% Local Functions
% Radar design parameters
function radar = designRadar(radarName)
radar.Name = radarName;
radar.AzScanStartElectronic = -60;
radar.AzScanStopElectronic = 60;
radar.AzimuthBeamwidth = [7;7];
radar.CFARMethod = 'GOCA';
radar.CFARNumCells = 32;
radar.CustomLoss = 3; % dB
radar.ElScanStartElectronic = 0;
radar.ElScanStopElectronic = 30;
radar.ElevationBeamwidth = [7;7];
radar.Frequency = 79000000000; % Hz
radar.Gain = [28.203489301781,28.203489301781];
radar.Height = 1.70000; % m
radar.MaxSpeed = 9.48710e+00;
radar.NoiseTemperature = 1500;
radar.NumCPIs = 1;
radar.NumCoherentPulses = 512;
radar.NumNonCoherentPulses = 1;
radar.PRF = 10000; % Hz
radar.PeakPower = 5.74000e+00; % W
radar.Pfa = 1.00000e-06;
radar.Polarization = 'H';
radar.PolarizationAngle = 0;
radar.PulseBandwidth = 4000000000; % Hz
radar.Pulsewidth = 5.00000e-05; % s
radar.RangeRateRes = 3.70590e-02;
radar.ReferenceNoiseTemperature = 290;
radar.STCCutOffRange = 1200; % m
radar.STCExponent = 3.50000e+00;
radar.TiltAngle = 0; % deg
radar.UnambiguousRange = 1.49896e+04;

% Convert frequency to wavelength
radar.Wavelength = freq2wavelen(radar.Frequency); % m

% Calculate system noise
radar.SystemTemperature = radar.NoiseTemperature; % Kelvin

% Calculate angular resolution
radar.EffectiveAzRes = effbeamwidth(radar.AzimuthBeamwidth(1),radar.AzimuthBeamwidth(2));     % deg
radar.EffectiveElRes = effbeamwidth(radar.ElevationBeamwidth(1),radar.ElevationBeamwidth(2)); % deg
end

%%
% Radar environment
function env = radarEnvironment()
env.EarthModel = 'Curved';
env.LatitudeModel = 'Standard';
env.PrecipitationMaxRange = 1500;
env.PrecipitationMinRange = 0;
env.RainPercentage = 1.00000e-02;
env.RainRate = 10;
env.SurfaceHeightStandardDeviation = 0; % m
env.SurfaceRelativePermittivity = -0.00000e+00-1i*1.00000e+16;
env.SurfaceSlope = 0; % deg
env.VegetationType = 'None';

% Calculate refractive index at surface
[env.RefractiveIndex,env.SurfaceRefractivity] = refractiveidx(0, ...
    'LatitudeModel',env.LatitudeModel);
env.RefractionExponent = refractionexp(env.SurfaceRefractivity);

% Set effective Earth radius
n = refractiveidx([0 1e3], ...
    'LatitudeModel',env.LatitudeModel);
RGradient = (n(2) - n(1))/1e3;
env.EffectiveEarthRadius = effearthradius(RGradient); % m
end

%%
% Radar target
function target = radarTarget(radar,env,rangeLimits)
target.ElevationAngle = 60;
target.RCS = 1.00000e-02; % m²
target.SwerlingCase = 'Swerling0';

% Calculate target position ranges
numTargetPositions = 1000;
target.ranges = linspace(rangeLimits(1),rangeLimits(2),numTargetPositions).'; % m
target.validRngIdxs = getValidRangeIdxs(radar,target,env);

% Calculate target height
target.Height = el2height(target.ElevationAngle,radar.Height,target.ranges, ...
    env.EarthModel,env.EffectiveEarthRadius); % m
end

%%
% Calculate propagation factor
function Fprop = propagationFactor(radar,env,target)
Fradarprop = -Inf(numel(target.ranges),2);
idxGteSurface = target.Height >= env.SurfaceHeightStandardDeviation;
for ie = 1:2
    Fradarprop(idxGteSurface,ie) = radarpropfactor(target.ranges(idxGteSurface),radar.Frequency,radar.Height,target.Height(idxGteSurface), ...
        'Polarization',radar.Polarization, ...
        'SurfaceRelativePermittivity',env.SurfaceRelativePermittivity, ...
        'SurfaceHeightStandardDeviation',env.SurfaceHeightStandardDeviation, ...
        'SurfaceSlope',env.SurfaceSlope, ...
        'VegetationType',env.VegetationType, ...
        'ElevationBeamwidth',radar.ElevationBeamwidth(ie), ...
        'TiltAngle',radar.TiltAngle, ...
        'EffectiveEarthRadius',env.EffectiveEarthRadius, ...
        'RefractiveIndex',env.RefractiveIndex);
end
Fradarprop(~idxGteSurface,:) = -inf;
Fprop = Fradarprop; % dB
end

%%
% Calculate environmental losses
function [Lgas,Llens,Lprecipitation] = atmosphericLosses(radar,env,target)
% Calculate atmospheric gas loss
Lgas = zeros(numel(target.ranges),1);
% Path loss due to atmosphere gaseous absorption. Valid for frequencies in range of 1 to 1000 GHz, inclusive.
idxs = target.validRngIdxs;
elevationAngles = target.ElevationAngle*ones(size(idxs));
Lgas(idxs) = tropopl(target.ranges(idxs),radar.Frequency,radar.Height,elevationAngles, ...
    'LatitudeModel',env.LatitudeModel);
% Calculate lens effect loss
Llens = zeros(numel(target.ranges),1);
idxs = target.validRngIdxs;
elevationAngles = target.ElevationAngle*ones(size(idxs));
Llens(idxs) = lenspl(target.ranges(idxs),radar.Height,elevationAngles, ...
    'LatitudeModel',env.LatitudeModel);

% Calculate precipitation loss
% Path loss due to rain. Valid for frequencies in range of 1 to 1000 GHz, inclusive. Not recommended for slant path propagation.
Lprecipitation = zeros(numel(target.ranges),1);
idxPrecipitation = target.ranges >= env.PrecipitationMinRange & target.validRngIdxs;
if any(idxPrecipitation)
    rangeExtentMax = env.PrecipitationMaxRange - env.PrecipitationMinRange;
    rangeExtent = target.ranges(idxPrecipitation) - env.PrecipitationMinRange;
    rangeExtent = min([rangeExtent,rangeExtentMax.*ones(numel(rangeExtent),1)],[],2);
    Lrain = rainpl(rangeExtent,radar.Frequency, ...
        env.RainRate,target.ElevationAngle, ...
        radar.PolarizationAngle,env.RainPercentage);
    Lprecipitation(idxPrecipitation) = Lrain;
end

end

%%
% Calculate range-dependent factors
function Fcustom = rangeDependentLosses(radar,target)
Fstc = stcfactor(target.ranges,radar.STCCutOffRange,radar.STCExponent);
Fcustom = Fstc; % dB
end

%%
% Get indices of geometrically valid ranges
function idxs = getValidRangeIdxs(radar,target,env)
anht = radar.Height + 2*env.SurfaceHeightStandardDeviation;
tgtht = inf;
minRng = 0;
maxRng = 2*env.EffectiveEarthRadius + tgtht + anht;
idxs = (target.ranges >= minRng & target.ranges <= maxRng);
end

%%
% Effective detectability factor for the selected radar
function [Dx,Dc,componentNames,processingGain] = effectiveDetectability(Pd,radar,target)
Pfa = radar.Pfa;
[Dc,componentNames] = detectabilityComponents(Pd,Pfa,radar.NumNonCoherentPulses,target.SwerlingCase,radar);
Dx = sum(Dc,2);
processingGain = -sum(Dc(:,2:end),2);
end

%%
% Losses and gains included in the detectability factor
function [Dc,names] = detectabilityComponents(Pd,Pfa,N,SW,radar)
% Single-pulse steady target
D01 = detectability(Pd,Pfa,1,'Swerling0');
% Coherent integration gain
Gci = -pow2db(radar.NumCoherentPulses)*ones(numel(Pd),1);
% CFAR loss
Lcfar = cfarloss(Pfa,radar.CFARNumCells,'Method',radar.CFARMethod);
Lcfar = Lcfar*ones(numel(Pd),1);
% Beam shape loss
Lbeam = beamloss(true);
Lbeam = Lbeam*ones(numel(Pd),1);
% Array scan loss
Larrayscan = 0;
azScanLimits = [radar.AzScanStartElectronic,radar.AzScanStopElectronic];
Larrayscan = Larrayscan + arrayscanloss(Pd,Pfa,N,azScanLimits,SW);
elScanLimits = [radar.ElScanStartElectronic,radar.ElScanStopElectronic];
Larrayscan = Larrayscan + arrayscanloss(Pd,Pfa,N,elScanLimits,SW);
% Custom loss
Lcustom = radar.CustomLoss*ones(numel(Pd),1);

Dc = [D01 Gci Lcfar Lbeam Larrayscan Lcustom];
names = {'Single-pulse steady target' 'Coherent integration gain' 'CFAR loss' 'Beam shape loss' 'Array scan loss' 'Custom loss'};
end

%%
% Set limits of the y axis for environmental losses plots
function setYLims(ax,x)
idx = isfinite(x);
minx = min(x(idx), [], 'all');
if isempty(minx)
    minx = 0;
end
maxx = max(x(idx), [], 'all');
if isempty(maxx)
    maxx = 0;
end
d = max((maxx - minx)/10, 0.1);
ylim(ax, [minx - d maxx + d]);
end
